from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()
kutuphane = []  # Geçici bellek listemiz

@app.post('/kitaplar', status_code=201)
def kitap_ekle(kitap: KitapKayit):
    yeni_veri = kitap.model_dump()  # Modeli Python sözlüğüne çevirir
    yeni_veri['id'] = len(kutuphane) + 1
    kutuphane.append(yeni_veri)
    return {'mesaj': 'Kitap başarıyla eklendi! 🎉', 'kitap': yeni_veri}

@app.get('/kitaplar')
def kitaplari_getir():
    return {
        'toplam_kitap': len(kutuphane),
        'kitaplar': kutuphane
    }

