class SiparisFormu(BaseModel):
    masa_no: int = Field(..., ge=1, le=50)
    urun: str
    adet: int = Field(1, gt=0)

@app.post('/kafe/siparis')
def siparis_al(siparis: SiparisFormu):
    return {'mesaj': f'Masa {siparis.masa_no} için {siparis.adet} adet {siparis.urun} mutfağa iletildi.'}

class BakiyeYukleme(BaseModel):
    kart_no: str = Field(..., min_length=5)
    tutar: float = Field(..., ge=10.0, le=1000.0)

@app.post('/yemekhane/yukle')
def yukleme_yap(islem: BakiyeYukleme):
    return {'durum': 'Yüklendi', 'kart': islem.kart_no, 'miktar': islem.tutar}

