from pydantic import field_validator

class SifreFormu(BaseModel):
    sifre: str

    @field_validator('sifre')
    @classmethod
    def sifre_guclu_mu(cls, v):
        if len(v) < 6:
            raise ValueError('Şifre en az 6 karakter olmalıdır!')
        return v

